/*!
 * PDF library: search and filters for subjects/<slug>/sources/index.html (generated by
 * tools/build_sources_pages.py). The page lists every file without this script; the script only
 * hides the rows that do not match. No storage. ?type=exam (or teoria, slides, problemas) opens the
 * page with that filter set.
 *
 * Markup it reads: #libTools (hidden until this runs), #libSearch, .lib-chip[data-filter][data-value],
 * select.lib-select[data-filter], .lib-row[data-only], .lib-item[data-kind|unit|exam|year|name],
 * .lib-group, #libCount, #libReset, #libEmpty.
 */
(function () {
  'use strict';
  var tools = document.getElementById('libTools');
  if (!tools) return;
  var search = document.getElementById('libSearch');
  var count = document.getElementById('libCount');
  var reset = document.getElementById('libReset');
  var empty = document.getElementById('libEmpty');
  var items = Array.prototype.slice.call(document.querySelectorAll('.lib-item'));
  var groups = Array.prototype.slice.call(document.querySelectorAll('.lib-group'));
  var chips = Array.prototype.slice.call(tools.querySelectorAll('.lib-chip'));
  var selects = Array.prototype.slice.call(tools.querySelectorAll('select.lib-select'));
  var rows = Array.prototype.slice.call(tools.querySelectorAll('.lib-row[data-only]'));
  var state = { q: '', kind: 'all', unit: 'all', exam: 'all', year: 'all' };

  function fold(text) {
    return String(text || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  }

  function matches(item) {
    if (state.kind !== 'all' && item.getAttribute('data-kind') !== state.kind) return false;
    if (state.unit !== 'all' && item.getAttribute('data-unit') !== state.unit) return false;
    if (state.exam !== 'all' && item.getAttribute('data-exam') !== state.exam) return false;
    if (state.year !== 'all' && item.getAttribute('data-year') !== state.year) return false;
    if (!state.q) return true;
    var hay = item.getAttribute('data-name');
    return state.q.split(/\s+/).every(function (word) { return hay.indexOf(word) !== -1; });
  }

  function apply() {
    // The exam filters only make sense for exams, the unit filter only for course material.
    rows.forEach(function (row) {
      var only = row.getAttribute('data-only');
      var show = only === 'exam' ? state.kind === 'exam' : state.kind !== 'exam';
      row.hidden = !show;
      if (!show) {
        Array.prototype.forEach.call(row.querySelectorAll('[data-filter]'), function (control) {
          state[control.getAttribute('data-filter')] = 'all';
        });
      }
    });
    chips.forEach(function (chip) {
      chip.setAttribute('aria-pressed', String(state[chip.getAttribute('data-filter')] === chip.getAttribute('data-value')));
    });
    selects.forEach(function (select) { select.value = state[select.getAttribute('data-filter')]; });

    var shown = 0;
    items.forEach(function (item) {
      var ok = matches(item);
      item.hidden = !ok;
      if (ok) shown++;
    });
    groups.forEach(function (group) { group.hidden = !group.querySelector('.lib-item:not([hidden])'); });
    var filtered = shown !== items.length;
    count.textContent = filtered ? shown + ' of ' + items.length + ' files' : items.length + ' files';
    reset.hidden = !filtered;
    empty.hidden = shown !== 0;
  }

  chips.forEach(function (chip) {
    chip.addEventListener('click', function () {
      state[chip.getAttribute('data-filter')] = chip.getAttribute('data-value');
      apply();
    });
  });
  selects.forEach(function (select) {
    select.addEventListener('change', function () {
      state[select.getAttribute('data-filter')] = select.value;
      apply();
    });
  });
  search.addEventListener('input', function () { state.q = fold(search.value).trim(); apply(); });
  reset.addEventListener('click', function () {
    state = { q: '', kind: 'all', unit: 'all', exam: 'all', year: 'all' };
    search.value = '';
    apply();
    search.focus();
  });

  var wanted = /[?&]type=([a-z]+)/.exec(location.search);
  if (wanted && tools.querySelector('.lib-chip[data-filter="kind"][data-value="' + wanted[1] + '"]')) state.kind = wanted[1];

  tools.hidden = false;
  apply();
})();
